let secrets;
try {
    secrets = JSON.parse(msg.payload);
} catch (e) {
    node.error('Could not parse secrets file: ' + e.message, msg);
    return null;
}
msg.secrets = secrets;
msg.job_started_at = new Date().toISOString();
const nowNs = Date.now() * 1000000;
msg.url = secrets.influxdb_url + '/api/v2/write?org=' + secrets.influxdb_org + '&bucket=' + secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'sync_job_runs,job_name=godaddy_backup,status=started value=1 ' + nowNs;
return msg;

msg.url = msg.secrets.godaddy_base_url + '/api/pull_manual_data.php?scope=all';
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.secrets.godaddy_api_sync_token };
return msg;

// Full backup — 5 record types only (Ward's own list: therapy sessions,
// medicine changes, weights, incidents, caffeine/alcohol — daily_log
// covers weight/caffeine/alcohol as columns on one table, not separate
// types). ecg_recording rows (if present in the response) are skipped
// here on purpose — no restore-side push endpoint exists for those yet.
const data = msg.payload;
if (!data || !Array.isArray(data.records)) {
    msg.job_failed = true;
    msg.failure_code = 'godaddy_error_response';
    msg.failure_detail = 'response missing records array: ' + JSON.stringify(data).slice(0, 300);
    return [null, msg];
}

const inScope = { incident: true, daily_log: true, therapy_session: true, medication: true, medication_dosage_history: true };
function escSql(s) { return "'" + String(s).replace(/'/g, "''") + "'"; }
const now = new Date().toISOString();
const rows = [];
data.records.forEach(r => {
    if (!inScope[r.record_type]) return;
    const sourceId = String((r.id !== undefined && r.id !== null) ? r.id : (Date.now() + '_' + Math.random()));
    rows.push('(' + escSql(r.record_type) + ',' + escSql(sourceId) + ',' + escSql(JSON.stringify(r)) + ',' + escSql(now) + ')');
});
msg.sqlite_row_count = rows.length;
msg.sqlite_insert_sql = rows.length
    ? 'INSERT OR REPLACE INTO godaddy_backup (record_type, source_id, data_json, backed_up_at) VALUES ' + rows.join(',')
    : null;

// Same InfluxDB line-building godaddy_pull_flow.json's own process
// function uses — deliberately duplicated rather than shared (Node-RED
// function nodes are self-contained; this project's established
// convention, see e.g. the SQLite ensure-table comment in that flow).
function esc(s) { return String(s).replace(/([ ,=])/g, '\\$1'); }
const lines = [];
const nowNs = Date.now() * 1000000;
data.records.forEach(r => {
    if (r.record_type === 'incident') {
        const ts = r.occurred_at ? new Date(r.occurred_at.replace(' ', 'T')).getTime() * 1000000 : nowNs;
        const parts = [];
        ['anxiety_intensity','duration_minutes','nitroglycerin_taken','related_medication_id'].forEach(f => {
            if (r[f] !== null && r[f] !== undefined) parts.push(f + '=' + r[f]);
        });
        ['chest_sensation','arm_sensation','shoulder_sensation','headache_sensation','shaking','stomach_sensation','flu_symptoms_sensation','lethargy_sensation'].forEach(f => {
            if (r[f]) parts.push(f + '="' + r[f] + '"');
        });
        // Numeric encoding alongside the string above (Aug 2026, Ward: "store
        // things like heart, headache and those pain thresholds as values in
        // influx so they can be processed") -- none/mild/moderate/severe as
        // 0/1/2/3 so Flux can do numeric work (trends, averages, threshold
        // crossing) on symptom severity, not just presence/absence clustering
        // (the one existing analysis that reads these fields today only ever
        // checks r.value !== 'none', never the gradation). Suffixed _level so
        // it can't collide with the existing string field of the same base
        // name -- InfluxDB fields are per-name-typed, so a string and a number
        // under one field name would be a type conflict.
        const sensationLevel = { none: 0, mild: 1, moderate: 2, severe: 3 };
        ['chest_sensation','arm_sensation','shoulder_sensation','headache_sensation','shaking','stomach_sensation','flu_symptoms_sensation','lethargy_sensation'].forEach(f => {
            if (r[f] && sensationLevel[r[f]] !== undefined) parts.push(f + '_level=' + sensationLevel[r[f]]);
        });
        if (parts.length) lines.push('incidents,category=' + esc(r.category) + ' ' + parts.join(',') + ' ' + ts);
    } else if (r.record_type === 'daily_log') {
        const ts = r.log_date ? new Date(r.log_date + 'T12:00:00').getTime() * 1000000 : nowNs;
        const parts = [];
        ['sleep_duration_hrs','sleep_efficiency','resting_hr','hrv','weight','steps','exercise_minutes','standing_minutes','caffeine_servings','alcohol_drinks','mood_rating','state_of_mind'].forEach(f => {
            if (r[f] !== null && r[f] !== undefined) parts.push(f + '=' + r[f]);
        });
        if (parts.length) lines.push('daily_log_manual,log_date=' + esc(r.log_date) + ' ' + parts.join(',') + ' ' + ts);
    } else if (r.record_type === 'therapy_session') {
        const ts = r.session_date ? new Date(r.session_date.replace(' ', 'T')).getTime() * 1000000 : nowNs;
        const parts = [];
        ['mood_before','mood_after'].forEach(f => { if (r[f] !== null && r[f] !== undefined) parts.push(f + '=' + r[f]); });
        if (parts.length) lines.push('therapy_sessions,session_type=' + esc(r.session_type || 'individual') + ' ' + parts.join(',') + ' ' + ts);
    } else if (r.record_type === 'medication') {
        const ts = r.start_date ? new Date(r.start_date + 'T12:00:00').getTime() * 1000000 : nowNs;
        const parts = ['frequency_days=' + (r.frequency_days || 1)];
        if (r.sort_order !== null && r.sort_order !== undefined) parts.push('sort_order=' + r.sort_order);
        parts.push('dosage="' + (r.dosage || '') + '"');
        parts.push('end_date="' + (r.end_date || '') + '"');
        parts.push('active=' + (r.end_date ? 'false' : 'true'));
        lines.push('medications,name=' + esc(r.name) + ',med_type=' + esc(r.med_type || 'scheduled') + ' ' + parts.join(',') + ' ' + ts);
    } else if (r.record_type === 'medication_dosage_history') {
        const ts = r.changed_at ? new Date(r.changed_at + 'T12:00:00').getTime() * 1000000 : nowNs;
        const parts = [];
        parts.push('old_dosage="' + (r.old_dosage || '') + '"');
        parts.push('new_dosage="' + (r.new_dosage || '') + '"');
        if (r.notes) parts.push('notes="' + esc(r.notes) + '"');
        lines.push('medication_dosage_history,medication_name=' + esc(r.medication_name || 'unknown') + ' ' + parts.join(',') + ' ' + ts);
    }
});
msg.influx_lines = lines;
msg.record_count = data.records.length;
return [msg, null];

// Idempotent CREATE, same discipline as sql/upgrade_from_3.0.0.sql on
// the GoDaddy side and godaddy_pull_flow.json's own job_status table.
// One raw-JSON-per-record row rather than a typed column per GoDaddy
// column on purpose — this table only ever needs to round-trip back
// through godaddy_restore_flow.json -> api/bulk_restore.php -> the same
// import_records() shape, never queried directly, so there's no schema
// to keep in sync with GoDaddy's own tables as they evolve.
msg.topic = "CREATE TABLE IF NOT EXISTS godaddy_backup (" +
    "record_type TEXT NOT NULL, source_id TEXT NOT NULL, data_json TEXT NOT NULL, " +
    "backed_up_at TEXT NOT NULL, PRIMARY KEY (record_type, source_id))";
return msg;

// Full REPLACE each run, not an accumulating log — every record type in
// scope was just re-fetched from GoDaddy above (scope=all), so clearing
// first means a record deleted on GoDaddy doesn't linger here forever as
// falsely 'restorable.' Cheap: this backup covers a single person's
// health-log tables, not a large dataset.
msg.topic = 'DELETE FROM godaddy_backup';
return msg;

if (!msg.sqlite_insert_sql) {
    // Nothing in scope this run (e.g. a genuinely empty GoDaddy database) —
    // the DELETE above still ran, which is correct: an empty source should
    // leave an empty backup, not a stale one.
    return null;
}
msg.topic = msg.sqlite_insert_sql;
return msg;

// Fire-and-forget, same pattern as godaddy_pull_flow.json's own
// InfluxDB write — job success/failure is driven off the SQLite path
// (the actual disaster-recovery copy), not off this correlation-only
// side write.
if (!msg.influx_lines.length) return null;
msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_lines.join('\n');
return msg;

const nowNs = Date.now() * 1000000;
const durationMs = Date.now() - new Date(msg.job_started_at).getTime();
msg.influx_finish_point = 'sync_job_runs,job_name=godaddy_backup,status=success record_count=' + (msg.record_count||0) + ',rows_backed_up=' + (msg.sqlite_row_count||0) + ',duration_ms=' + durationMs + ' ' + nowNs;
msg.sqlite_job = { job_name: 'godaddy_backup', mode: 'success', last_success: new Date().toISOString(), last_attempt: new Date().toISOString(), last_attempt_ok: 1 };
return msg;

const nowNs = Date.now() * 1000000;
const code = msg.failure_code || 'unknown_error';
const detail = (msg.failure_detail || '').replace(/([ ,="])/g, '\\$1');
msg.influx_finish_point = 'sync_job_runs,job_name=godaddy_backup,status=failed,failure_code=' + code + ' detail="' + detail + '" ' + nowNs;
msg.sqlite_job = { job_name: 'godaddy_backup', mode: 'failure', last_attempt: new Date().toISOString(), last_attempt_ok: 0, last_error: code + ': ' + (msg.failure_detail || '') };
node.warn('GoDaddy backup failed: ' + code + ' - ' + msg.failure_detail);
return msg;

msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_finish_point;
return msg;

msg.topic = "CREATE TABLE IF NOT EXISTS job_status (" +
    "job_name TEXT PRIMARY KEY, last_success TEXT, last_attempt TEXT, " +
    "last_attempt_ok INTEGER, last_error TEXT, checkpoint TEXT, updated_at TEXT)";
return msg;

function esc(s) { return "'" + String(s).replace(/'/g, "''") + "'"; }
function sqlVal(v) { return (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? v : esc(v)); }
const j = msg.sqlite_job;
const now = new Date().toISOString();
const cols = ['job_name', 'last_success', 'last_attempt', 'last_attempt_ok', 'last_error', 'checkpoint', 'updated_at'];
const vals = [j.job_name, j.last_success ?? null, j.last_attempt, j.last_attempt_ok, j.last_error ?? null, j.checkpoint ?? null, now];
const setClauses = ['last_attempt=excluded.last_attempt', 'last_attempt_ok=excluded.last_attempt_ok', 'updated_at=excluded.updated_at'];
if (j.mode === 'success') {
    setClauses.push('last_success=excluded.last_success', 'last_error=NULL');
} else {
    setClauses.push('last_error=excluded.last_error');
}
msg.topic = 'INSERT INTO job_status (' + cols.join(', ') + ') VALUES (' + vals.map(sqlVal).join(', ') + ') ' +
    'ON CONFLICT(job_name) DO UPDATE SET ' + setClauses.join(', ');
return msg;
